        "mirror",
        "--yes",
        "--ignore-case",
        "--exclude",
        "\u{dc}bung",
        "--exclude",
        "\u{3c3}*",
        "--exclude",
        "stra\u{df}e",
        &with_slash(&src),
        &with_slash(&dst),
    ]);
    assert_eq!(code, Some(0), "stdout:\n{out}\nstderr:\n{err}");
    for kept in [
        "\u{fc}bung/saved.txt",
        "x/\u{3c2}.txt",
        "STRA\u{1e9e}E/saved.txt",
