        fs::write(dst.join("X.TXT"), "x").unwrap();
        fs::write(dst.join("extra.dat"), "x").unwrap();
        let stored = fs::write(src.join(name(b"\xfe.TXT")), "in the source")
            .and_then(|()| fs::write(dst.join(name(b"\xff.TXT")), "destination only"));
