    let (_tmp, src, dst, _) = fixture();
    let (ok, out, err) = blit(&[
        "mirror",
        "--yes",
        "--exclude",
        "???.TXT",
        &with_slash(&src),
        &with_slash(&dst),
    ]);
    assert!(ok, "{out}{err}");
    assert!(!dst.join(name(b"\xff.TXT")).exists(), "not named: deleted");
